import{_ as i,a as n,c as l,ac as a}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"第四册：流利英语 · 单元 2：时间、条件与社会系统","description":"L9–L16 的学习目标、课时入口和复习方法。","frontmatter":{"title":"第四册：流利英语 · 单元 2：时间、条件与社会系统","description":"L9–L16 的学习目标、课时入口和复习方法。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","summary":"L9–L16 的学习目标、课时入口和复习方法。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 单元 1 复习与自测","link":"/life/english/new-concept/book-4/unit-01/review"},"next":{"text":"第四册：流利英语 · 单元 2 语法总结","link":"/life/english/new-concept/book-4/unit-02/grammar"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 单元 1 复习与自测","link":"/life/english/new-concept/book-4/unit-01/review"},"next":{"text":"第四册：流利英语 · 单元 2 语法总结","link":"/life/english/new-concept/book-4/unit-02/grammar"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-02/overview.md","filePath":"life/english/new-concept/book-4/unit-02/overview.md"}'),o={name:"life/english/new-concept/book-4/unit-02/overview.md"};function t(s,e,r,c,h,u){return n(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="第四册-流利英语-·-单元-2-时间、条件与社会系统" tabindex="-1">第四册：流利英语 · 单元 2：时间、条件与社会系统 <a class="header-anchor" href="#第四册-流利英语-·-单元-2-时间、条件与社会系统" aria-label="Permalink to &quot;第四册：流利英语 · 单元 2：时间、条件与社会系统&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-02/overview">单元导读</a> · <a href="/life/english/new-concept/book-4/unit-02/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-4/unit-02/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-4/unit-02/review">单元复习与自测</a></p><h2 id="单元导读" tabindex="-1">单元导读 <a class="header-anchor" href="#单元导读" aria-label="Permalink to &quot;单元导读&quot;">​</a></h2><p>L9–L16。第9—16课连接历史消息、产业集群、年龄议论、银行服务、勘探、复杂系统、工业保密和城市设计。学习把多层信息整理成时间线、条件分支和因果链，而不是只记连接词的中文意思。特别检查条件未满足时会发生什么、比较双方是否同类，以及目的是否真的已经实现；用可检验的小情境支持社会议论。</p><p>本栏目按连续课号组织学习单元；单元主题与复习任务为本站编排，便于分阶段学习，不作为各印次教材目录的替代。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>梳理过去前情与未来条件</li><li>使用比较、目的和结果结构</li><li>解释条款与假设的适用边界</li></ul><h2 id="课时目录" tabindex="-1">课时目录 <a class="header-anchor" href="#课时目录" aria-label="Permalink to &quot;课时目录&quot;">​</a></h2><ul><li><a href="/life/english/new-concept/book-4/unit-02/lesson-009">Lesson 9 · Royal espionage</a></li><li><a href="/life/english/new-concept/book-4/unit-02/lesson-010">Lesson 10 · Silicon Valley</a></li><li><a href="/life/english/new-concept/book-4/unit-02/lesson-011">Lesson 11 · How to grow old</a></li><li><a href="/life/english/new-concept/book-4/unit-02/lesson-012">Lesson 12 · Banks and their customers</a></li><li><a href="/life/english/new-concept/book-4/unit-02/lesson-013">Lesson 13 · The search for oil</a></li><li><a href="/life/english/new-concept/book-4/unit-02/lesson-014">Lesson 14 · The Butterfly Effect</a></li><li><a href="/life/english/new-concept/book-4/unit-02/lesson-015">Lesson 15 · Secrecy in industry</a></li><li><a href="/life/english/new-concept/book-4/unit-02/lesson-016">Lesson 16 · The modern city</a></li></ul><h2 id="单元知识地图" tabindex="-1">单元知识地图 <a class="header-anchor" href="#单元知识地图" aria-label="Permalink to &quot;单元知识地图&quot;">​</a></h2><ul><li>L9：过去完成时与过去叙事参照点。不能仅因故事发生在古代就整篇用 had done；先确定两个过去动作的关系。</li><li>L10：比较结构与范围限定。rents are lower than the city centre 把租金与地点比较，应补 those in。</li><li>L11：动名词短语作主语。Learning new skills are rewarding 中 are 应改 is；skills 只是动名词的宾语。</li><li>L12：unless 与条件从句。unless the customer will sign 不用于这里的普通未来条件；应写 signs。</li><li>L13：目的不定式与 so that。不要把 to collect 与 because collected 混淆：前者说明目的，后者说明已经发生的原因。</li><li>L14：第二条件句与假设距离。不要看到 changed 就一律解释成过去已发生；在本条件句里它表示假设距离。</li><li>L15：whether 引导名词性从句。whether can the data be shared 是错误疑问语序；嵌入从句用 whether the data can be shared。</li><li>L16：so…that 与 such…that 的结果表达。such far away 结构错误；没有名词短语时应使用 so far away。</li></ul><h2 id="完成标准" tabindex="-1">完成标准 <a class="header-anchor" href="#完成标准" aria-label="Permalink to &quot;完成标准&quot;">​</a></h2><p>能用自己的例子说明上面的语法点；能在不看答案时完成单元自测；能完成至少一项口头表达和一项书面表达，并根据课时点评修订。若做错，不必整单元重学，沿题目链接回到相应课时。</p>',13)])])}const p=i(o,[["render",t]]);export{f as __pageData,p as default};
